import {plansFor,getPlan,planName,priceLabel,planOptions,detailRoute,planRoute} from './catalogue.js';
import {catalogueHTML,detailHTML,comparisonHTML,pricingNoteHTML} from './plan-ui.js';
import { company, categories, faqs, coverageStates, troubleshooting } from './content.js';
import {escapeHTML as esc,formHTML,fieldHTML,addressFields,contactFields} from './forms.js';
import {aboutPageHTML,contactDetailsHTML} from './company-pages.js';
export const link=(route,label,secondary=false)=>`<a class="ik-button${secondary?' ik-button-secondary':''}" href="#/${route}">${label}</a>`;
const actions=(...items)=>`<div class="ik-actions">${items.join('')}</div>`;
const section=(title,body,tint=false)=>`<section class="ik-section${tint?' ik-tint':''}"><div class="ik-wrap">${title?`<h2>${title}</h2>`:''}${body}</div></section>`;
const notice=text=>`<p class="ik-notice">${text}</p>`;
const photo=(purpose)=>`<div class="ik-image-slot" data-slot="${({'Residential lifestyle':'residential','Business collaboration':'business','Workplace connectivity':'solution','Company and people':'about'})[purpose]}" role="img" aria-label="Reserved photography: ${purpose}"><span>Photography reserved<br>Phase 2 · ${purpose}</span></div>`;
const editorial=(title,copy,purpose,buttons='')=>section('',`<div class="ik-editorial"><div><h2>${title}</h2><p class="ik-muted">${copy}</p>${buttons}</div>${photo(purpose)}</div>`);
const tile=(title,copy,route,cta='Explore')=>`<article class="ik-panel"><h3>${title}</h3><p>${copy}</p>${link(route,cta)}</article>`;
const grid=(...items)=>`<div class="ik-grid">${items.join('')}</div>`;
const faqHTML=(items)=>items.map(([category,q,a])=>`<details class="ik-faq" data-category="${category}"><summary>${q}</summary><p>${a}</p></details>`).join('');
const cta=(title,copy,route,label)=>section(title,`<p class="ik-muted">${copy}</p>${actions(link(route,label))}`,true);
const selectedPlan=state=>{const plan=getPlan(state.plan);return plan?.audience===state.audience?plan:null;};
const journey=(route,state)=>planRoute(route,selectedPlan(state),state.audience);
const residentialCatalogue=()=>catalogueHTML('residential')+actions(link('residential/compare','Compare Plans',true),link('coverage?audience=residential','Check Coverage'),link('residential/installation','Installation Enquiry',true));
const planField=audience=>field('plan','Selected plan',{optional:true,options:planOptions(audience),help:'Preview selection. Pricing and service terms require client confirmation.'});

const field=(name,label,extra={})=>({name,label,...extra});
const comments=field('comments','Additional information',{type:'textarea',optional:true});
const account=field('account','Customer account reference',{optional:true,help:'Do not share passwords or one-time codes.'});
const supportFields=[account,...contactFields,field('address','Service address'),field('category','Fault category',{options:['No internet connection','Slow connection','Wi-Fi','Router','Other']}),field('description','Description',{type:'textarea'}),field('preferred','Preferred contact method',{options:['Email','Phone']})];
export function supportSearchHTML(query={}) {
  return `<div class="ik-help-search" role="search">${fieldHTML(field('search','Search help',{optional:true}),{search:query.search||''},'help')}${fieldHTML(field('category','Help category',{optional:true,noBlank:true,options:[['','All topics'],...categories]}),{category:query.category||''},'help')}</div><p id="ik-search-count" class="ik-muted" role="status" aria-live="polite"></p><div id="ik-search-results">${faqHTML(faqs)}</div>`;
}
export function renderPage(path,{state,query,template}) {
  switch(path) {
  case 'residential': return editorial('Made for everyday moments.','From video calls to movie nights, make room for everything you do online.','Residential lifestyle',actions(link('residential/plans','Explore Residential Plans')))+section('Internet for the way you live.',grid(tile('Work from home','Stay connected through meetings and daily tasks.','residential/plans'),tile('Connect the household','Enjoy shows, music and everyday browsing across your family’s devices.','residential/plans')),true)+section('Available residential plans',residentialCatalogue())+section('Getting connected.',`<ol class="ik-steps"><li>Check your address.</li><li>Discuss a suitable plan and installation requirements.</li><li>Arrange the next steps with the team once eligibility is confirmed.</li></ol>${actions(link('residential/installation','Installation Enquiry'))}`,true)+section('Installation questions',faqHTML(faqs.filter(x=>x[0]==='coverage')))+cta('Ready to get connected?','Start by checking availability at your address.','coverage','Check Coverage');
  case 'residential/plans':return section('Find your connection.',residentialCatalogue())+section('Plan questions',faqHTML(faqs.filter(x=>['coverage','payments'].includes(x[0]))),true);
  case 'residential/plans/demo-1':case 'residential/plans/demo-2':{const id=query.get('plan')||(path.endsWith('2')?'res-isilver':'res-ibasic'),plan=getPlan(id);if(!plan||plan.audience!=='residential')return section('Plan not found',actions(link('residential/plans','View Residential Plans')));return section('',detailHTML(plan))+section('Relevant questions',faqHTML(faqs.filter(x=>['coverage','payments'].includes(x[0]))));}
  case 'residential/compare':{const items=plansFor('residential'),first=items.find(p=>p.id===query.get('first'))||items[0],second=items.find(p=>p.id===query.get('second'))||items[2];return section('Compare your options',`<div class="ik-form">${fieldHTML(field('first','First plan',{noBlank:true,options:planOptions('residential')}),{first:first.id},'compare')}${fieldHTML(field('second','Second plan',{noBlank:true,options:planOptions('residential')}),{second:second.id},'compare')}</div><div id="ik-comparison">${comparisonHTML(first.id,second.id)}</div>`)+cta('Explore every option.','Browse the full residential catalogue.','residential/plans','All Residential Plans');}
  case 'residential/installation':return section('Your installation enquiry',formHTML('installation',[...contactFields,...addressFields.slice(1,3),field('district','Area or estate'),field('street','Street / address'),planField('residential'),comments],'Preview Enquiry',{...state.address,plan:state.plan||''}))+cta('Need help first?','Review coverage or ask a general question.',journey('coverage',state),'Check Coverage');
  case 'business':return editorial('Keep business moving.','From daily communication to connected teams, find a service that fits your operations.','Business collaboration',actions(link('business/solutions','Explore Solutions')))+section('Built around different needs.',businessSegments(),true)+section('Explore business connectivity.',catalogueHTML('business')+grid(tile('Business connectivity','Discuss suitable options and service considerations.','business/solutions/connectivity','View Solution Details')))+cta("Let’s talk about your business.",'Share your requirements with our team.','business/quote','Request a Quote');
  case 'business/solutions':return section('Explore business requirements',notice('SME and Enterprise are customer segments, not verified product names or service guarantees.')+businessSegments()+grid(tile('Business connectivity','Service features are subject to approved solution definitions.','business/solutions/connectivity','View Solution Details')))+cta('Discuss your requirements.','Service options depend on the address and technical requirements.','business/plans','Business Plans');
  case 'business/solutions/connectivity':case 'business/solutions/sme':case 'business/solutions/enterprise':return editorial('A connection around your requirements.','From households and estates to offices and organisations, Ikonectt supports different connectivity requirements.','Workplace connectivity')+section('Service considerations',notice('Solution-detail preview. No product specification, uptime, SLA, equipment, or performance guarantee has been verified.')+`<div class="ik-table-wrap"><table class="ik-table"><tbody><tr><th scope="row">${path.endsWith('connectivity')?'Solution':'Customer segment'}</th><td>${path.endsWith('sme')?'Small and growing businesses':path.endsWith('enterprise')?'Enterprise organisations':'Business connectivity (definition pending)'}</td></tr><tr><th scope="row">Verified features</th><td>Awaiting approved product definitions</td></tr><tr><th scope="row">Suitable applications</th><td>Discuss team, workplace, and connectivity requirements</td></tr><tr><th scope="row">Service considerations</th><td>Address, technical feasibility, equipment, installation and contract terms require confirmation</td></tr></tbody></table></div>`)+cta('Talk to the team.','Share your location and requirements.','business/quote','Request a Quote');
  case 'business/plans':return section('Business connectivity',`<p class="ik-intro">Compare published business speeds and monthly pricing, then discuss the right connection for your organisation.</p>${catalogueHTML('business')}${actions(link('business/quote','Request a Quote'),link('business/solutions','Explore Solutions',true),link('coverage?audience=business','Check Coverage',true))}`);
  case 'business/quote':return section('Your business requirements',formHTML('quote',[field('company','Company name',{autocomplete:'organization'}),field('name','Contact name',{autocomplete:'name'}),field('email','Business email',{type:'email',autocomplete:'email'}),contactFields[2],field('location','Business location'),field('businessType','Business type'),field('interest','Service interest',{options:['Business connectivity','SME requirements','Enterprise requirements','Help choosing a service']}),planField('business'),field('requirements','Connectivity requirements',{type:'textarea'}),field('comments','Additional comments',{type:'textarea',optional:true})],'Preview Quote Request',{plan:state.plan||''}));
  case 'coverage':return section('Your address',notice('Demonstration checker. There is no live coverage endpoint. Select a scenario to review the experience; the address is never used to infer availability.')+formHTML('coverage',[field('audience','Connection for',{noBlank:true,options:[['residential','Residential'],['business','Business']]}),planField(state.audience),...addressFields],'Review Demonstration Result',{country:'Nigeria',...state.address,audience:state.audience,plan:state.plan||''},`<div class="ik-full">${fieldHTML(field('scenario','Demonstration result to preview',{noBlank:true,help:'A preview scenario, not a real result for your address.',options:Object.entries(coverageStates).map(([key,value])=>[key,value.title])}),{scenario:'unknown'},'coverage')}</div>`));
  case 'coverage/results':return coverageResult(state);
  case 'coverage/verification':return section('Request an address review',formHTML('verification',[...contactFields,...addressFields,planField(state.audience),field('landmark','Nearest landmark',{optional:true}),comments],'Preview Verification Request',{country:'Nigeria',...state.address,plan:state.plan||''}));
  case 'support':return section('Search for an answer',supportSearchHTML())+section('Browse help topics',grid(...categories.map(([key,label])=>tile(label,'',`support/faqs?category=${key}`,'Browse topic'))),true)+section('More ways to get help',grid(tile('Troubleshooting','Follow guided checks before choosing a support action.','support/troubleshooting','Start Troubleshooting'),tile('Report a Fault','Describe a connection or equipment problem.','support/fault','Report a Fault'),tile('Service Request','Choose the assistance you need.','support/service-request','Service Request')))+cta('Need to speak to the team?','General enquiries do not require a sign-in.','support/contact','Contact Support');
  case 'support/faqs':return section('Browse answers',supportSearchHTML({category:categories.some(([key])=>key===query.get('category'))?query.get('category'):'',search:query.get('search')||''}))+cta('Still need help?','Find a troubleshooting guide or describe the issue.','support/troubleshooting','Troubleshooting')+section('',actions(link('support/fault','Report a Fault'),link('support/contact','Contact Support',true)));
  case 'support/troubleshooting':return troubleshootingPage(query);
  case 'support/fault':return section('Your fault report',formHTML('fault',supportFields,'Preview Fault Report',{address:Object.values(state.address||{}).filter(Boolean).join(', ')}));
  case 'support/service-request':return section('How can we help?',formHTML('service',[account,...contactFields,field('category','Request category',{options:['Installation assistance','Account access assistance','Plan or renewal question','Service change enquiry','Complaint','Other request']}),field('address','Service address',{optional:true}),field('description','Request details',{type:'textarea'}),field('preferred','Preferred contact method',{options:['Email','Phone']})],'Preview Service Request'));
  case 'support/contact':return section('Contact options',contactDetailsHTML()+formHTML('support',[...contactFields,account,field('category','Issue category',{options:categories.map(([,label])=>label)}),field('message','Your message',{type:'textarea'})],'Preview Support Request'));
  case 'about':
   if(template==='e')return aboutPageHTML();
   return editorial('About Ikonectt.',company.description,'Company and people')+section('Built around different needs.','<p class="ik-muted">From households and estates to offices and organisations, Ikonectt supports different connectivity requirements.</p>',true)+cta('Find the right connection.','Explore home and business broadband options.','contact','Contact');
  case 'contact':return section('Get in touch',contactDetailsHTML())+section('Choose a pathway',grid(tile('General enquiry','Ask about Ikonectt services.','contact?enquiry=general','General Enquiry'),tile('Residential enquiry','Discuss home broadband and installation.','residential/installation','Installation Enquiry'),tile('Business enquiry','Share your organisation’s requirements.','business/quote','Request a Quote'),tile('Technical support','Find help with an existing connection.','support','Help Centre')))+section('Send an enquiry',formHTML('contact',[contactFields[0],contactFields[1],{...contactFields[2],optional:true},field('type','Enquiry type',{options:['General enquiry','Residential enquiry','Business enquiry','Customer support']}),field('message','Your message',{type:'textarea'})],'Preview Message'),true);
  case 'privacy':case 'terms':return section('Publication pending',notice(`Client-approved ${path==='privacy'?'privacy policy':'terms and conditions'}, effective date and last-updated date are required. This is a structural placeholder and is not a legal policy.`)+actions(link('contact','Contact'),link('home','Home',true)));
  case 'my-ikonectt/sign-in':return section('Sign in',notice('Interface preview only. Production authentication is not implemented. Use sample credentials; no login succeeds in this preview.')+formHTML('sign-in',[field('account','Account number',{autocomplete:'username',help:'Use the account number supplied through internal onboarding. Official formats will be supported.'}),field('password','Password',{type:'password',autocomplete:'current-password'})],'Preview Sign In')+actions(link('my-ikonectt/forgot-password','Forgot Password',true),link('support/contact','Contact Support',true),link('my-ikonectt/preview','View Portal Preview',true))+'<p class="ik-notice">Customer onboarding is staff-managed. There is no public registration.</p>');
  case 'my-ikonectt/forgot-password':return section('Recover access',formHTML('recovery',[field('account','Account number',{autocomplete:'username'})],'Preview Recovery')+actions(link('my-ikonectt/sign-in','Back to Sign In',true),link('support/contact','Contact Support',true)));
  case 'my-ikonectt/preview':return section('Portal preview',notice('You are not signed in. No private customer information is loaded or shown.')+grid(tile('Your services','Service information requires authenticated access.','my-ikonectt/sign-in','Sign In Preview'),tile('Payments and renewals','Billing and payment integrations are not connected.','support/contact','Ask for Help'),tile('Support requests','Public help remains available without login.','support','Help Centre')));
  default:return section('Page not found','<p>The requested page is not part of this preview.</p>'+actions(link('home','Return Home'),link('support','Help Centre',true)));
  }
}
function businessSegments(){return grid(tile('SME Connectivity','For small and growing business requirements.','business/solutions/sme','Explore SME Segment'),tile('Enterprise Connectivity','For organisation and workplace requirements.','business/solutions/enterprise','Explore Enterprise Segment'));}
function coverageResult(state){
  if(!state.coverage) return section('No address check to review',notice('Start a demonstration address check. A direct link or page refresh does not contain an address or a stored result.')+actions(link(journey('coverage',state),'Check Address'),link(journey(state.audience+'/plans',state),state.audience==='business'?'Explore Business Plans':'Explore Residential Plans',true)));
  const result=Object.hasOwn(coverageStates,state.coverage)?coverageStates[state.coverage]:coverageStates.unknown;
  return section('',`<div class="ik-result"><span class="ik-badge">Demonstration result · Not a live coverage decision</span><h2>${result.title}</h2><p>${result.text}</p><p class="ik-notice">Address entered: ${esc(addressFields.map(field=>state.address[field.name]).filter(Boolean).join(', '))}</p>${actions(link(journey(state.audience==='business'&&state.coverage==='available'?'business/quote':result.route,state),state.audience==='business'&&state.coverage==='available'?'Request a Quote':result.action),link(journey(state.audience+'/plans',state),state.audience==='business'?'Explore Business Plans':'Explore Residential Plans',true),link(journey('coverage',state),'Check Another Address',true))}</div>`);
}
function troubleshootingPage(query){
  const topic=query.get('topic'),guide=Object.hasOwn(troubleshooting,topic)?troubleshooting[topic]:null;
  if(!guide) return section('Choose a topic',notice('These are guided checks, not automated diagnostics. No network or account test is running.')+grid(...Object.entries(troubleshooting).map(([key,value])=>tile(value.title,'',`support/troubleshooting?topic=${key}&step=0`,'Start Guide'))));
  const step=Math.min(guide.steps.length-1,Math.max(0,Number.parseInt(query.get('step')||'0',10)||0));
  return section(guide.title,`<span class="ik-badge">Step ${step+1} of ${guide.steps.length}</span><p>${guide.steps[step]}</p>${actions(...(step?[link(`support/troubleshooting?topic=${topic}&step=${step-1}`,'Previous',true)]:[]),...(step<guide.steps.length-1?[link(`support/troubleshooting?topic=${topic}&step=${step+1}`,'Next Step')]:[link('support/fault','Report a Fault'),link('support/contact','Contact Support',true)]),link('support/troubleshooting','All Guides',true))}`);
}
export function filterFAQs(search='',category='') {
  const value=search.toLocaleLowerCase().trim();
  return faqs.filter(([key,q,a])=>(!category||key===category)&&(!value||(q+' '+a).toLocaleLowerCase().includes(value)));
}
export function renderFAQResults(items){return items.length?faqHTML(items):'<p class="ik-notice">No matching answers. Try another search or use Contact Support.</p>';}

